/* ot_assets.h -- the pictures and tables the Windows build carries as executable resources (button icon drawings, the HD
 * texture index), read from files on other hosts.
 *
 * <assets>/resources.txt lists "NAME relative/path" per line (generated by macos/launcher/make_resources.py from
 * port/src/ssx_recomp.rc.in); <assets> is OT_ASSET_DIR, else <executable folder>/assets, else the folder the build was made
 * from (OT_DEFAULT_ASSET_DIR). Each file is read once and kept. */
#ifndef OT_ASSETS_H
#define OT_ASSETS_H
#include <stddef.h>

/* The bytes of resource `name` (valid for the life of the process), or NULL if the name or file is missing. */
const void *ot_asset(const char *name, size_t *size);

#endif
